// SQL generation for the loader (Stage 5).
//
// The loader writes three COPY TSV files + one transaction SQL file per
// source run, all staged under /tmp (see pg.ts for why), then applies the
// SQL with psql. One transaction per run (L7): any failure rolls the whole
// run back and the run row is marked 'failed' by the driver.
//
// Staging files (COPY text format, tab-delimited, \N = NULL):
//   licenses.tsv   — one row per normalized license (this run)
//   businesses.tsv — one row per deduped business (business_id is a UUID
//                    generated by the driver so the SQL can map
//                    business_key -> business id without a second lookup)
//   dedupe.tsv     — one row per license that belongs to a decided cluster
//
// Business identity across runs (Dd6): a license seen before keeps its
// previous business; only NEW licenses take the business from this run's
// dedupe. A NEW business reuses an existing business row when name +
// phone/address evidence matches it.

import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { BusinessRow, DedupeDecision } from "./dedupe.ts";
import type { NormalizedRecord } from "./normalize.ts";

// COPY text format escaping: backslash, tab, newline, carriage return.
export function tsvEscape(value: string | null | undefined): string {
  if (value === null || value === undefined) return "\\N";
  return value
    .replace(/\\/g, "\\\\")
    .replace(/\t/g, "\\t")
    .replace(/\n/g, "\\n")
    .replace(/\r/g, "\\r");
}

function tsvCell(value: string | null | undefined): string {
  return tsvEscape(value);
}

function sqlQuote(value: string): string {
  return `'${value.replace(/'/g, "''")}'`;
}

export interface StagingBusiness extends BusinessRow {
  id: string; // driver-generated UUID for the business row
  stateCode: string; // 'TX' default when the source gives no state
}

export interface StagingFiles {
  businessCount: number;
  decisionCount: number;
  dir: string;
  licenseCount: number;
}

export function writeStagingFiles(
  dir: string,
  records: NormalizedRecord[],
  assignmentsBusinessKey: string[],
  businesses: StagingBusiness[],
  decisions: DedupeDecision[],
): StagingFiles {
  mkdirSync(dir, { recursive: true });
  const licLines: string[] = [];
  records.forEach((r, i) => {
    const addr = r.address;
    licLines.push(
      [
        assignmentsBusinessKey[i],
        r.license_type,
        r.license_number,
        r.license_subtype,
        r.expiration_date,
        r.issue_date,
        r.license_status,
        r.verification_level,
        r.license_status_source,
        r.status_as_of,
        JSON.stringify(r.endorsements),
        r.insurance?.company ?? null,
        r.insurance?.expiry_date ?? null,
        r.county ?? addr?.county ?? null,
        r.business_name,
        r.business_name_normalized,
        r.holder?.full_name ?? null,
        r.holder?.first_name ?? null,
        r.holder?.last_name ?? null,
        r.holder?.middle_name ?? null,
        r.holder?.suffix ?? null,
        r.phone,
        r.phone_normalized,
        addr?.line1 ?? null,
        addr?.line2 ?? null,
        addr?.city ?? null,
        addr?.state ?? null,
        addr?.zip ?? null,
        addr?.county ?? null,
        addr?.county_code ?? null,
      ]
        .map(tsvCell)
        .join("\t"),
    );
  });
  const bizLines: string[] = businesses.map((b) =>
    [
      b.id,
      b.businessKey,
      b.displayName,
      b.normalizedName,
      b.phone,
      b.phoneNormalized,
      b.address?.line1 ?? null,
      b.address?.line2 ?? null,
      b.address?.city ?? null,
      b.stateCode,
      b.address?.zip ?? null,
      b.address?.county ?? null,
      b.dedupeStatus,
      b.nameFallback ? "t" : "f",
    ]
      .map(tsvCell)
      .join("\t"),
  );
  const dedupeLines: string[] = [];
  for (const d of decisions) {
    for (const idx of d.licenseIndexes) {
      const r = records[idx];
      dedupeLines.push(
        [
          d.clusterKey,
          r.license_type,
          r.license_number,
          d.decision,
          d.rationale,
          d.businessKey,
        ]
          .map(tsvCell)
          .join("\t"),
      );
    }
  }
  writeFileSync(join(dir, "licenses.tsv"), licLines.join("\n") + "\n", "utf8");
  writeFileSync(join(dir, "businesses.tsv"), bizLines.join("\n") + "\n", "utf8");
  writeFileSync(join(dir, "dedupe.tsv"), dedupeLines.join("\n") + "\n", "utf8");
  return {
    businessCount: businesses.length,
    decisionCount: decisions.length,
    dir,
    licenseCount: records.length,
  };
}

export interface RunSqlOptions {
  dir: string;
  downloaded: number;
  notes: string;
  parsed: number;
  runId: string;
  sourceCode: string;
  trade: string;
}

export function buildRunSql(opts: RunSqlOptions): string {
  const code = sqlQuote(opts.sourceCode);
  const trade = sqlQuote(opts.trade);
  const runId = sqlQuote(opts.runId);
  const dir = opts.dir;
  const notes = sqlQuote(opts.notes);
  return `-- House Craft Pros ETL load — source ${opts.sourceCode}, run ${opts.runId}
-- Generated by etl/src/sqlgen.ts. One transaction per run (L7).
BEGIN;

CREATE TEMP TABLE ctx AS
SELECT (SELECT id FROM data_sources WHERE code = ${code}) AS source_id,
       ${runId}::uuid AS run_id;

CREATE TEMP TABLE stg_lic (
  business_key text NOT NULL,
  license_type text NOT NULL,
  license_number text NOT NULL,
  license_subtype text,
  expiration_date date,
  issue_date date,
  license_status text NOT NULL,
  verification_level text NOT NULL,
  license_status_source text NOT NULL,
  status_as_of date NOT NULL,
  endorsements text NOT NULL,
  insurance_company text,
  insurance_expiry_date date,
  county text,
  business_name text,
  business_name_normalized text,
  holder_full_name text,
  holder_first_name text,
  holder_last_name text,
  holder_middle_name text,
  holder_suffix text,
  phone text,
  phone_normalized text,
  addr_line1 text,
  addr_line2 text,
  addr_city text,
  addr_state text,
  addr_zip text,
  addr_county text,
  addr_county_code text
);
COPY stg_lic FROM '${dir}/licenses.tsv' WITH (FORMAT text, DELIMITER E'\\t', NULL '\\N');

CREATE TEMP TABLE stg_biz (
  business_id uuid NOT NULL,
  business_key text NOT NULL,
  name text NOT NULL,
  normalized_name text NOT NULL,
  phone text,
  phone_normalized text,
  address_line1 text,
  address_line2 text,
  city text,
  state_code text NOT NULL,
  zip text,
  county text,
  dedupe_status text NOT NULL,
  name_fallback boolean NOT NULL
);
COPY stg_biz FROM '${dir}/businesses.tsv' WITH (FORMAT text, DELIMITER E'\\t', NULL '\\N');

CREATE TEMP TABLE stg_dedupe (
  cluster_key text NOT NULL,
  license_type text NOT NULL,
  license_number text NOT NULL,
  decision text NOT NULL,
  rationale text NOT NULL,
  business_key text
);
COPY stg_dedupe FROM '${dir}/dedupe.tsv' WITH (FORMAT text, DELIMITER E'\\t', NULL '\\N');

-- Holders: find-or-create by exact full_name (L9, no fuzzy matching).
INSERT INTO license_holders (full_name, first_name, last_name, middle_name, suffix)
SELECT DISTINCT holder_full_name, holder_first_name, holder_last_name, holder_middle_name, holder_suffix
FROM stg_lic
WHERE holder_full_name IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM license_holders h WHERE h.full_name = stg_lic.holder_full_name);

-- Locations: find-or-create (L10). County-level when city is NULL.
INSERT INTO locations (state_code, county_name, city_name)
SELECT DISTINCT COALESCE(addr_state, 'TX'), addr_county, addr_city
FROM stg_lic
WHERE addr_county IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM locations loc
    WHERE loc.state_code = COALESCE(stg_lic.addr_state, 'TX')
      AND loc.county_name = stg_lic.addr_county
      AND loc.city_name IS NOT DISTINCT FROM stg_lic.addr_city
  );

-- Business mapping: reuse an existing business on name + phone/address
-- evidence (cross-run dedupe, Dd6); the rest get new rows.
CREATE TEMP TABLE biz_map (business_key text PRIMARY KEY, business_id uuid NOT NULL);
INSERT INTO biz_map (business_key, business_id)
SELECT DISTINCT ON (sb.business_key) sb.business_key, b.id
FROM stg_biz sb
JOIN businesses b ON b.normalized_name = sb.normalized_name
  AND (
    (b.phone_normalized IS NOT NULL AND sb.phone_normalized IS NOT NULL AND b.phone_normalized = sb.phone_normalized)
    OR (b.address_line1 IS NOT NULL AND sb.address_line1 IS NOT NULL
        AND lower(btrim(b.address_line1)) = lower(btrim(sb.address_line1))
        AND b.city IS NOT DISTINCT FROM sb.city
        AND b.zip IS NOT DISTINCT FROM sb.zip)
  )
ORDER BY sb.business_key, b.created_at ASC, b.id ASC;

INSERT INTO businesses (id, name, normalized_name, phone, phone_normalized, address_line1, address_line2, city, state_code, zip, county, location_id, dedupe_status, first_seen_run_id, last_seen_run_id)
SELECT sb.business_id, sb.name, sb.normalized_name, sb.phone, sb.phone_normalized, sb.address_line1, sb.address_line2, sb.city, sb.state_code, sb.zip, sb.county,
  (SELECT loc.id FROM locations loc WHERE loc.state_code = sb.state_code AND loc.county_name = sb.county AND loc.city_name IS NOT DISTINCT FROM sb.city LIMIT 1),
  sb.dedupe_status, (SELECT run_id FROM ctx), (SELECT run_id FROM ctx)
FROM stg_biz sb
WHERE NOT EXISTS (SELECT 1 FROM biz_map m WHERE m.business_key = sb.business_key);

INSERT INTO biz_map (business_key, business_id)
SELECT sb.business_key, sb.business_id FROM stg_biz sb
WHERE NOT EXISTS (SELECT 1 FROM biz_map m WHERE m.business_key = sb.business_key);

-- Touch reused businesses (new ones already carry this run id).
UPDATE businesses b SET last_seen_run_id = (SELECT run_id FROM ctx), updated_at = now()
FROM biz_map m
WHERE b.id = m.business_id
  AND NOT EXISTS (SELECT 1 FROM stg_biz sb WHERE sb.business_id = b.id);

-- Snapshot of the licenses this run will touch (for history + counts).
CREATE TEMP TABLE lic_before AS
SELECT l.id, l.license_status AS prev_status, l.verification_level AS prev_verification,
       l.disappeared_from_source AS was_disappeared
FROM licenses l
JOIN stg_lic s ON s.license_type = l.license_type AND s.license_number = l.license_number
WHERE l.source_id = (SELECT source_id FROM ctx);

-- New licenses (L3: upsert by identity, never delete).
INSERT INTO licenses (business_id, holder_id, source_id, ingestion_run_id, contract_version, trade, license_type, license_subtype, license_number, expiration_date, issue_date, license_status, verification_level, license_status_source, status_as_of, endorsements, insurance_company, insurance_expiry_date, county, location_id)
SELECT m.business_id,
  (SELECT h.id FROM license_holders h WHERE h.full_name = s.holder_full_name LIMIT 1),
  (SELECT source_id FROM ctx), (SELECT run_id FROM ctx), 'v1', ${trade},
  s.license_type, s.license_subtype, s.license_number, s.expiration_date, s.issue_date,
  s.license_status, s.verification_level, s.license_status_source, s.status_as_of,
  s.endorsements::jsonb, s.insurance_company, s.insurance_expiry_date, s.county,
  (SELECT loc.id FROM locations loc WHERE loc.state_code = COALESCE(s.addr_state, 'TX') AND loc.county_name = s.addr_county AND loc.city_name IS NOT DISTINCT FROM s.addr_city LIMIT 1)
FROM stg_lic s
JOIN biz_map m ON m.business_key = s.business_key
WHERE NOT EXISTS (
  SELECT 1 FROM licenses l WHERE l.source_id = (SELECT source_id FROM ctx)
    AND l.license_type = s.license_type AND l.license_number = s.license_number
);

-- Existing licenses: update mutable fields, keep the previous business (Dd6).
UPDATE licenses l SET
  holder_id = (SELECT h.id FROM license_holders h WHERE h.full_name = s.holder_full_name LIMIT 1),
  ingestion_run_id = (SELECT run_id FROM ctx),
  license_subtype = s.license_subtype,
  expiration_date = s.expiration_date,
  issue_date = s.issue_date,
  license_status = s.license_status,
  verification_level = s.verification_level,
  license_status_source = s.license_status_source,
  status_as_of = s.status_as_of,
  endorsements = s.endorsements::jsonb,
  insurance_company = s.insurance_company,
  insurance_expiry_date = s.insurance_expiry_date,
  county = s.county,
  location_id = (SELECT loc.id FROM locations loc WHERE loc.state_code = COALESCE(s.addr_state, 'TX') AND loc.county_name = s.addr_county AND loc.city_name IS NOT DISTINCT FROM s.addr_city LIMIT 1),
  disappeared_from_source = false,
  disappeared_at = NULL,
  last_seen_at = now()
FROM stg_lic s
WHERE l.source_id = (SELECT source_id FROM ctx)
  AND l.license_type = s.license_type AND l.license_number = s.license_number;

-- History: initial load (L4).
INSERT INTO license_status_history (license_id, previous_status, new_status, previous_verification_level, new_verification_level, change_reason, run_id)
SELECT l.id, NULL, l.license_status, NULL, l.verification_level, 'initial_load', (SELECT run_id FROM ctx)
FROM licenses l
WHERE l.source_id = (SELECT source_id FROM ctx)
  AND l.ingestion_run_id = (SELECT run_id FROM ctx)
  AND NOT EXISTS (SELECT 1 FROM lic_before b WHERE b.id = l.id);

-- History: status/verification changed (L4 — unchanged records get NO row).
INSERT INTO license_status_history (license_id, previous_status, new_status, previous_verification_level, new_verification_level, change_reason, run_id)
SELECT l.id, b.prev_status, l.license_status, b.prev_verification, l.verification_level,
  CASE WHEN s.license_status_source = 'source_field' THEN 'source_status_change'
       WHEN l.license_status = 'expired' AND b.prev_status = 'active' THEN 'expiration_passed'
       ELSE 'source_status_change' END,
  (SELECT run_id FROM ctx)
FROM licenses l
JOIN lic_before b ON b.id = l.id
JOIN stg_lic s ON s.license_type = l.license_type AND s.license_number = l.license_number
WHERE l.license_status <> b.prev_status OR l.verification_level <> b.prev_verification;

-- History: reappeared in source (L5).
INSERT INTO license_status_history (license_id, previous_status, new_status, previous_verification_level, new_verification_level, change_reason, run_id)
SELECT l.id, l.license_status, l.license_status, l.verification_level, l.verification_level, 'reappeared_in_source', (SELECT run_id FROM ctx)
FROM licenses l
JOIN lic_before b ON b.id = l.id
WHERE b.was_disappeared = true;

-- Disappeared from source (L5): marked, never deleted.
CREATE TEMP TABLE lic_disappeared AS
SELECT l.id FROM licenses l
WHERE l.source_id = (SELECT source_id FROM ctx)
  AND l.disappeared_from_source = false
  AND NOT EXISTS (SELECT 1 FROM stg_lic s WHERE s.license_type = l.license_type AND s.license_number = l.license_number);

UPDATE licenses l SET disappeared_from_source = true, disappeared_at = now()
FROM lic_disappeared d WHERE l.id = d.id;

INSERT INTO license_status_history (license_id, previous_status, new_status, previous_verification_level, new_verification_level, change_reason, run_id)
SELECT l.id, l.license_status, l.license_status, l.verification_level, l.verification_level, 'disappeared_from_source', (SELECT run_id FROM ctx)
FROM licenses l
JOIN lic_disappeared d ON d.id = l.id;

-- Dedupe decisions (US3): one row per decided cluster, license ids as array.
INSERT INTO dedupe_decisions (run_id, cluster_key, license_ids, business_id, decision, rationale, decided_by)
SELECT (SELECT run_id FROM ctx), d.cluster_key,
  array_agg(l.id ORDER BY l.license_number),
  CASE WHEN d.decision = 'merged' THEN (SELECT m.business_id FROM biz_map m WHERE m.business_key = d.business_key LIMIT 1) ELSE NULL END,
  d.decision, d.rationale, 'etl'
FROM stg_dedupe d
JOIN licenses l ON l.source_id = (SELECT source_id FROM ctx) AND l.license_type = d.license_type AND l.license_number = d.license_number
GROUP BY d.cluster_key, d.decision, d.rationale, d.business_key;

-- Audit: business-name fallback to holder name is recorded, not hidden (L11).
INSERT INTO audit_logs (actor, action, table_name, record_id, new_values, run_id)
SELECT 'etl', 'business.name_fallback', 'businesses', sb.business_id,
  jsonb_build_object('name', sb.name, 'fallback_from_holder', true, 'business_key', sb.business_key),
  (SELECT run_id FROM ctx)
FROM stg_biz sb
JOIN businesses b ON b.id = sb.business_id
WHERE sb.name_fallback = true;

-- A 'single' business that now holds >= 2 licenses becomes 'merged'.
UPDATE businesses b SET dedupe_status = 'merged'
WHERE b.dedupe_status = 'single'
  AND (SELECT count(*) FROM licenses l WHERE l.business_id = b.id) >= 2;

-- Close the run (V2 reconciliation is checked by the driver after load).
UPDATE ingestion_runs r SET
  status = 'succeeded',
  finished_at = now(),
  row_count_downloaded = ${opts.downloaded},
  row_count_parsed = ${opts.parsed},
  row_count_loaded = (SELECT count(*) FROM stg_lic),
  row_count_new = (SELECT count(*) FROM licenses l WHERE l.source_id = (SELECT source_id FROM ctx) AND l.ingestion_run_id = (SELECT run_id FROM ctx) AND NOT EXISTS (SELECT 1 FROM lic_before b WHERE b.id = l.id)),
  row_count_changed = (SELECT count(*) FROM license_status_history h WHERE h.run_id = (SELECT run_id FROM ctx) AND h.change_reason IN ('expiration_passed', 'source_status_change')),
  row_count_disappeared = (SELECT count(*) FROM lic_disappeared),
  notes = ${notes}
WHERE r.id = (SELECT run_id FROM ctx);

COMMIT;
`;
}
